INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('58feb66d-98de-5755-a19e-2d785d83f3ca','TEXT','The Windy Sculpture','Kai liked helping at the community hall, especially when there was a small job that nobody had planned. One Saturday, Kai noticed the reed sculpture was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Kai decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('6efa889c-b8d2-5854-adb4-b2999cc3403c','TEXT','A Lantern for the Jetty — A Different Day','Mia liked helping at the sea fog, especially when there was a small job that nobody had planned. One Wednesday, Mia noticed the jetty lantern was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Mia decided to stop and look carefully instead of rushing.
