INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('0f5f047d-d4c8-5173-8c1a-86c5d3ce4686','TEXT','A Lantern for the Jetty','Mia liked helping at the sea fog, especially when there was a small job that nobody had planned. One Wednesday, Mia noticed the jetty lantern was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Mia decided to stop and look carefully instead of rushing.
