INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('667ccfea-5257-53c8-a884-29f0de1c96c1','TEXT','The Night Garden List','Ruby liked helping at the backyard habitat, especially when there was a small job that nobody had planned. One Thursday, Ruby noticed the garden list was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Ruby decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('ab8521ec-f876-5c94-aa74-41c3922c389c','TEXT','The Museum Window — A Different Day','Luca liked helping at the local museum, especially when there was a small job that nobody had planned. One Friday, Luca noticed the old window frame was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Luca decided to stop and look carefully instead of rushing.
